public class Main {
    public static void main(String[] args) {
        int num = 28;
        String parity = (num % 2 == 0) ? "EVEN" : "ODD";
        System.out.println("Number " + num + " is " + parity);
    }
}

public class Main {
    public static void main(String[] args) {
        int cartAmount = 420;
        int fee = (cartAmount >= 500) ? 0 : 50;
        int finalBill = cartAmount + fee;
        System.out.println("Cart: Rs " + cartAmount + " | Delivery Fee: Rs " + fee + " | Final: Rs " + finalBill);
    }
}

public class Main {
    public static void main(String[] args) {
        boolean isStudent = true;
        int rate = isStudent ? 15 : 0;
        int discount = (1000 * rate) / 100;
        System.out.println("Discount Rate: " + rate + "% | Discount Amount: Rs " + discount);
    }
}
